///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name search
 * @description search 처리
 * @returns {void}
 * @hidden N
 */
scwin.search = function () {
    let url = "";
    const type = $c.util.getComponent('ipt_searchType_2').getValue();
    if (type.substring(0, 4) === "WRNT") {
        url = "/common/corp.do?method=elwCorpNmList&search_type=" + type;
    } else {
        if ($c.util.getComponent('ipt_searchType_2').getValue() === "SPECLBND") {
            url = "/common/corp.do?method=specCorpNmList&search_type=SPECLBND";
        } else {
            if ($c.util.getComponent('ipt_searchType_2').getValue() === "BENFCERT") {
                url = "/common/corp.do?method=benefCorpNmList&search_type=BENFCERT";
            } else {
                if ($c.util.getComponent('ipt_searchType_2').getValue() === "DR") {
                    url = "/common/corp.do?method=elwCorpNmList&search_type=DR";
                } else {
                    url = "/common/corp.do?method=corpNmList";
                }
            }
        }
    }
    (document.JLDINF90400 || { elements: [] }).action = url;
    const p = {}; p["itemId"] = $c.util.getComponent("ipt_itemId").getValue(); p["itemNm"] = $c.util.getComponent("ipt_itemNm").getValue(); p["searchType"] = $c.util.getComponent("ipt_searchType_2").getValue(); p["elwYn"] = $c.util.getComponent("elwYn").getValue(); p["searchWord"] = $c.util.getComponent("ipt_searchWord").getValue(); p["pageIndex"] = $c.util.getComponent("pageIndex").getValue(); $c.win.setPageFrameSrc($c.win.getFrame(), '/ui/jsp/JLDINF90400.xml', p);
};

